#![cfg(feature = "json")]

//! Feature vectors for proof sidecars and three-way merge.
//!
//! Both features are driven from a checked-in index, so the vectors are
//! generated by `examples/generate_vectors.rs` and verified through the shipped
//! public API. A change that alters proof acceptance or merge output shows up as
//! a reviewable diff in `tests/vectors/`, not as a silent behavior change.

use std::fs;
use std::path::PathBuf;

use active_infinity::{content_hash, decode, encode, ir::hash_hex, merge, Merge, Proof};

fn vectors() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/vectors")
}

fn cases(path: &PathBuf) -> Vec<Vec<String>> {
    let index = fs::read_to_string(path).expect("index");
    index
        .lines()
        .filter(|line| !line.starts_with('#') && !line.trim().is_empty())
        .map(|line| line.split_whitespace().map(str::to_string).collect())
        .collect()
}

#[test]
fn proof_vectors_follow_their_index() {
    let dir = vectors().join("proof");
    let rows = cases(&dir.join("index.txt"));
    assert_eq!(rows.len(), 3, "the index must list three proof cases");
    for row in rows {
        assert_eq!(row.len(), 4, "{row:?}");
        let image = fs::read(dir.join(&row[1])).expect("image");
        let text = fs::read_to_string(dir.join(&row[2])).expect("sidecar");
        let proof = Proof::from_json(&text).expect("parse sidecar");
        let outcome = proof.verify(&image);
        match row[3].as_str() {
            "ok" => outcome.expect("the vector must verify"),
            code => {
                let error = outcome.expect_err("the vector must be refused");
                assert_eq!(error.code(), code, "{}", row[0]);
            }
        }
    }
}

#[test]
fn the_proof_vectors_cover_accept_tamper_and_wrong_image() {
    let dir = vectors().join("proof");
    let rows = cases(&dir.join("index.txt"));
    let accepted = rows.iter().filter(|row| row[3] == "ok").count();
    let refused = rows.iter().filter(|row| row[3] != "ok").count();
    assert_eq!(accepted, 1);
    assert_eq!(refused, 2);
}

#[test]
fn merge_vectors_follow_their_index() {
    let dir = vectors().join("merge");
    let rows = cases(&dir.join("index.txt"));
    assert_eq!(rows.len(), 3, "the index must list three merge cases");
    for row in rows {
        assert_eq!(row.len(), 5, "{row:?}");
        let base = decode(&fs::read(dir.join(&row[1])).expect("base")).expect("decode base");
        let left = decode(&fs::read(dir.join(&row[2])).expect("left")).expect("decode left");
        let right = decode(&fs::read(dir.join(&row[3])).expect("right")).expect("decode right");
        match merge(&base, &left, &right).expect("merge") {
            Merge::Clean(module) => {
                let expected = row[4]
                    .strip_prefix("clean:")
                    .unwrap_or_else(|| panic!("a clean case must say clean:<hash>: {row:?}"));
                let bytes = encode(&module).expect("encode merged");
                let hash = hash_hex(&content_hash(&bytes).expect("hash"));
                assert_eq!(hash, expected, "{}", row[0]);
                let golden =
                    fs::read(dir.join(format!("{}.merged.ainf", row[0]))).expect("merged vector");
                assert_eq!(bytes, golden, "the merged bytes must match the vector");
            }
            Merge::Conflicts(conflicts) => {
                let rendered: Vec<String> = conflicts
                    .iter()
                    .map(|conflict| format!("{}:{:?}", conflict.field, conflict.kind))
                    .collect();
                assert_eq!(
                    format!("conflict:{}", rendered.join(",")),
                    row[4],
                    "{}",
                    row[0]
                );
            }
        }
    }
}

#[test]
fn the_nested_merge_vector_names_the_leaf_and_the_metadata_vector_names_the_component() {
    let text = fs::read_to_string(vectors().join("merge/index.txt")).expect("index");
    assert!(text.contains("conflict:server.port:ModifyModify"), "{text}");
    assert!(text.contains("conflict:<bindings>:KindMismatch"), "{text}");
}
